from collections import Counter

def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    # find all diagonal segments (len>=2, non-bg) with their cells and color
    segs=[]
    for dr,dc in ((1,1),(1,-1)):
        for r in range(h):
            for c in range(w):
                pr,pc=r-dr,c-dc
                if 0<=pr<h and 0<=pc<w and g[pr][pc]==g[r][c] and g[r][c]!=bg:
                    continue  # not a segment start
                col=g[r][c]; cells=[]; rr,cc=r,c
                while 0<=rr<h and 0<=cc<w and g[rr][cc]==col:
                    cells.append((rr,cc)); rr+=dr; cc+=dc
                if len(cells)>=2:
                    segs.append((col,cells))
    for col,cells in segs:
        rows=set(r for r,c in cells)
        # foreign rows: rows of any other segment's cells
        foreign=set()
        for col2,cells2 in segs:
            if cells2 is not cells:
                foreign |= set(r for r,c in cells2)
        for end,dr,dc in ((cells[0],-1,-1) if cells[0][0]<=cells[-1][0] else (cells[0],0,0),):
            pass
        # two ray directions: from each end outward along the segment direction
        (r0,c0),(r1,c1)=cells[0],cells[-1]
        dr=r1-r0; dc=c1-c0
        for sr,sc,sdr,sdc in ((r0,c0,-dr,-dc),(r1,c1,dr,dc)):
            ray=[]; rr,cc=sr+sdr,sc+sdc
            while 0<=rr<h and 0<=cc<w and g[rr][cc]==bg:
                ray.append((rr,cc)); rr+=sdr; cc+=sdc
            if not ray: continue
            # suppress if any ray cell's row is a foreign row
            if any(rr in foreign for rr,c in ray): continue
            for rr,cc in ray: out[rr][cc]=col
    return out

